func NewClickHouseEventBatch(eventName string) ClickHouseEventBatch {
	switch eventName {
	case "ConditionPreparation", "ConditionalTokensConditionPreparation":
		return NewConditionalTokensConditionPreparationBatch()
	case "ConditionResolution", "ConditionalTokensConditionResolution":
		return NewConditionalTokensConditionResolutionBatch()
	case "PositionSplit", "ConditionalTokensPositionSplit":
		return NewConditionalTokensPositionSplitBatch()
	case "PositionsMerge", "ConditionalTokensPositionsMerge":
		return NewConditionalTokensPositionsMergeBatch()
	case "PayoutRedemption", "ConditionalTokensPayoutRedemption":
		return NewConditionalTokensPayoutRedemptionBatch()
	case "OrderFilled", "ExchangeOrderFilled":
		return NewExchangeOrderFilledBatch()
	case "NegRiskExchangeOrderFilled":
		return NewNegRiskExchangeOrderFilledBatch()
	case "MarketPrepared", "NegRiskAdapterMarketPrepared":
		return NewNegRiskAdapterMarketPreparedBatch()
	case "QuestionPrepared", "NegRiskAdapterQuestionPrepared":
		return NewNegRiskAdapterQuestionPreparedBatch()
	case "NegRiskAdapterPositionSplit":
		return NewNegRiskAdapterPositionSplitBatch()
	case "NegRiskAdapterPositionsMerge":
		return NewNegRiskAdapterPositionsMergeBatch()
	case "PositionsConverted", "NegRiskAdapterPositionsConverted":
		return NewNegRiskAdapterPositionsConvertedBatch()
	case "NegRiskAdapterPayoutRedemption":
		return NewNegRiskAdapterPayoutRedemptionBatch()
	case "FixedProductMarketMakerCreation", "FixedProductMarketMakerFactoryFixedProductMarketMakerCreation":
		return NewFixedProductMarketMakerFactoryFixedProductMarketMakerCreationBatch()
	case "FPMMBuy", "FixedProductMarketMakerFPMMBuy":
		return NewFixedProductMarketMakerFPMMBuyBatch()
	case "FPMMSell", "FixedProductMarketMakerFPMMSell":
		return NewFixedProductMarketMakerFPMMSellBatch()
	case "FPMMFundingAdded", "FixedProductMarketMakerFPMMFundingAdded":
		return NewFixedProductMarketMakerFPMMFundingAddedBatch()
	case "FPMMFundingRemoved", "FixedProductMarketMakerFPMMFundingRemoved":
		return NewFixedProductMarketMakerFPMMFundingRemovedBatch()
	default:
		return nil
	}
}
